import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  GraduationCap,
  Award,
  TrendingUp,
  RotateCcw,
  ShieldCheck,
  CheckCircle2,
  Brain,
  Layers,
  ArrowRight,
  Flame,
  User,
  Activity,
} from 'lucide-react';
import { api } from '../../api/client';
import { StudentProgressData } from '../../types/student';
import { useUser } from '../../context/UserContext';
import DisclaimerBanner from '../../components/common/DisclaimerBanner';

const StudentProfilePage: React.FC = () => {
  const { profile, updateProfileName } = useUser();
  const [progress, setProgress] = useState<StudentProgressData | null>(null);
  const [loading, setLoading] = useState(true);
  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(profile.name);

  useEffect(() => {
    const fetchProgress = async () => {
      try {
        const data = await api.getStudentProgress();
        setProgress(data);
      } catch (err) {
        console.error('Failed to load student progress:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchProgress();
  }, []);

  const handleSaveName = () => {
    if (tempName.trim()) {
      updateProfileName(tempName.trim());
    }
    setIsEditingName(false);
  };

  const conceptBars = progress?.concepts_mastered
    ? Object.entries(progress.concepts_mastered)
    : [
        ['Edges', 60],
        ['Textures', 50],
        ['Shapes', 75],
        ['Intensity', 40],
        ['CNN Basics', 70],
        ['Spatial Pattern', 55],
      ];

  const topicsToRevise = progress?.topics_to_revise || [
    'Infiltrative vs Circumscribed Edges',
    'Differentiating Vasogenic Edema from Enhancing Core',
    'Grad-CAM Receptive Field Interpretation',
    'Pituitary Sellar Expansion on Coronal Views',
  ];

  return (
    <div className="space-y-8 max-w-7xl mx-auto">
      {/* Profile Header */}
      <div className="p-8 rounded-3xl bg-slate-900/70 border border-slate-800 space-y-6 relative overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center space-x-4">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-teal-500 to-cyan-400 p-0.5 shadow-xl shadow-teal-500/20">
              <div className="w-full h-full bg-slate-950 rounded-[14px] flex items-center justify-center text-teal-300">
                <GraduationCap className="w-8 h-8" />
              </div>
            </div>
            <div className="space-y-1">
              <div className="flex items-center space-x-2">
                {isEditingName ? (
                  <div className="flex items-center space-x-2">
                    <input
                      type="text"
                      value={tempName}
                      onChange={(e) => setTempName(e.target.value)}
                      className="bg-slate-950 border border-teal-500/50 rounded-lg px-2.5 py-1 text-sm font-bold text-white focus:outline-none"
                    />
                    <button
                      onClick={handleSaveName}
                      className="px-2.5 py-1 rounded-lg bg-teal-500 text-slate-950 text-xs font-bold"
                    >
                      Save
                    </button>
                  </div>
                ) : (
                  <>
                    <h1 className="text-xl sm:text-2xl font-bold text-white">{profile.name}</h1>
                    <button
                      onClick={() => setIsEditingName(true)}
                      className="text-xs text-slate-400 hover:text-teal-400"
                    >
                      (Edit)
                    </button>
                  </>
                )}
                <span className="text-[10px] font-mono uppercase bg-teal-500/10 text-teal-300 border border-teal-500/20 px-2 py-0.5 rounded-full font-bold">
                  Role: Medical Student
                </span>
              </div>
              <p className="text-xs text-slate-400 font-mono">{profile.title}</p>
              <p className="text-xs text-slate-500">{profile.institution}</p>
            </div>
          </div>

          <div className="flex items-center space-x-2 text-xs font-mono text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 px-3.5 py-2 rounded-xl shrink-0">
            <ShieldCheck className="w-4 h-4 text-emerald-400" />
            <span>Strict Student/Patient Separation Active</span>
          </div>
        </div>
      </div>

      <DisclaimerBanner />

      {/* KPI Stats Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-1">
          <span className="text-xs text-slate-400">Cases Completed</span>
          <p className="text-2xl font-bold text-teal-400">{progress?.cases_completed || 2}</p>
          <span className="text-[10px] text-slate-500">Practice Sets</span>
        </div>
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-1">
          <span className="text-xs text-slate-400">Quizzes Solved</span>
          <p className="text-2xl font-bold text-cyan-400">
            {progress?.quizzes_correct || 0} / {progress?.quizzes_attempted || 0}
          </p>
          <span className="text-[10px] text-slate-500">Assessment Questions</span>
        </div>
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-1">
          <span className="text-xs text-slate-400">Learning Streak</span>
          <div className="flex items-center space-x-1.5">
            <Flame className="w-5 h-5 text-amber-400 fill-amber-400" />
            <p className="text-2xl font-bold text-amber-400">{progress?.streak_days || 1}d</p>
          </div>
          <span className="text-[10px] text-slate-500">Active Study</span>
        </div>
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-1">
          <span className="text-xs text-slate-400">Concepts Explored</span>
          <p className="text-2xl font-bold text-purple-400">7 Core</p>
          <span className="text-[10px] text-slate-500">Edges to High-Level</span>
        </div>
      </div>

      {/* Detailed Concept Mastery & Automated Revision */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Mastery Breakdown */}
        <div className="p-6 rounded-3xl bg-slate-900/60 border border-slate-800 space-y-4">
          <div className="flex items-center justify-between border-b border-slate-800 pb-3">
            <div className="flex items-center space-x-2 text-white font-bold text-sm">
              <TrendingUp className="w-4 h-4 text-teal-400" />
              <span>MRI Concept Mastery (Learning Progress)</span>
            </div>
            <span className="text-[10px] font-mono text-slate-400">Reflective Metric</span>
          </div>

          <div className="space-y-3">
            {conceptBars.map(([concept, pct]) => (
              <div key={concept} className="space-y-1">
                <div className="flex justify-between text-xs">
                  <span className="font-semibold text-slate-300">{concept}</span>
                  <span className="font-mono text-teal-400">{pct}%</span>
                </div>
                <div className="w-full h-2 rounded-full bg-slate-950 overflow-hidden border border-slate-800/80">
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-teal-500 to-cyan-400"
                    style={{ width: `${pct}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Automated Revision Recommendations */}
        <div className="p-6 rounded-3xl bg-slate-900/60 border border-slate-800 space-y-4">
          <div className="flex items-center justify-between border-b border-slate-800 pb-3">
            <div className="flex items-center space-x-2 text-white font-bold text-sm">
              <RotateCcw className="w-4 h-4 text-amber-400" />
              <span>Personalized Topics to Revise</span>
            </div>
            <span className="text-[10px] font-mono text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-500/20">
              Needs Reinforcement
            </span>
          </div>

          <div className="space-y-2">
            {topicsToRevise.map((topic, i) => (
              <div
                key={i}
                className="p-3 rounded-xl bg-slate-950/70 border border-slate-800 flex items-start space-x-3 text-xs"
              >
                <div className="w-5 h-5 rounded-full bg-amber-500/10 border border-amber-500/20 text-amber-400 flex items-center justify-center shrink-0 mt-0.5 text-[10px] font-mono">
                  {i + 1}
                </div>
                <div className="space-y-0.5">
                  <p className="font-semibold text-slate-200">{topic}</p>
                  <p className="text-[11px] text-slate-400">
                    Flagged from previous case reasoning iterations and concept check submissions.
                  </p>
                </div>
              </div>
            ))}
          </div>

          <div className="pt-2 flex justify-end">
            <Link
              to="/student/quizzes"
              className="text-xs text-teal-400 hover:text-teal-300 font-semibold flex items-center space-x-1"
            >
              <span>Practice in Quiz Lab</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentProfilePage;
